/* Darkhorse identity: the D / horse mark, forward-cut stripes, ink + mint. */
@font-face{font-family:Anton;src:url('assets/fonts/anton.ttf') format('truetype');font-style:normal;font-weight:400;font-display:swap}
:root{--bg:#090e0d;--ink:#f0f0e6;--muted:#a9b9b3;--line:#31433b;--green:#78f5c6;--lime:#78f5c6;--brand-mint:#78f5c6;--brand-gold:#e9c883;--brand-display:Anton,'Barlow Condensed',Impact,sans-serif}
body{background:radial-gradient(ellipse at 95% 10%,#17403150,transparent 35%),#090e0d;color:var(--ink)}body::before{background:none}body main{max-width:1440px;padding:0 4% 24px}body p{line-height:1.7}body h2{font-family:var(--brand-display);font-weight:400;letter-spacing:.005em;font-size:clamp(28px,3vw,40px)}body h3{letter-spacing:-.025em}body .tiny{font-size:12px;color:#afbeb7}body a{color:#9de9c9}body button,body input,body select{font-family:Inter,Arial,sans-serif}body button:focus-visible,body a:focus-visible,body select:focus-visible,body input:focus-visible,body summary:focus-visible{outline:2px solid var(--brand-mint);outline-offset:5px}body .brand-skip{position:absolute;left:20px;top:-90px;background:#78f5c6;color:#09120d;padding:12px;z-index:100}.brand-skip:focus{top:10px!important}
body header.darkhorse-header{max-width:1440px;margin:auto;padding:0 4%;position:relative;background:transparent}body .masthead-foot{max-width:none;display:flex;justify-content:space-between;gap:16px;margin:0;padding:17px 0;border-bottom:1px solid #34453c;font:500 9px/1.5 Inter,sans-serif;letter-spacing:.12em}.masthead-foot .status{color:#a9cdbb}.masthead-foot .status:before{content:'';display:inline-block;width:5px;height:5px;margin-right:8px;background:#78f5c6;border-radius:50%}
body .dh-brand{display:inline-flex;align-items:center;gap:18px;margin:22px auto 18px;text-decoration:none;color:#f0f0e6;text-align:left;letter-spacing:0}.dh-brand>img{width:76px;height:76px;object-fit:contain}.dh-brand .brand-lockup{color:inherit;display:grid;grid-template-columns:1fr auto;align-items:center;column-gap:14px}.brand-lockup>strong{font:400 48px/.98 var(--brand-display);letter-spacing:.01em;grid-column:1/3}.brand-lockup>small{font:600 9px/1.8 Inter,sans-serif;letter-spacing:.36em}.brand-lockup>small:first-child{grid-column:1/3}.brand-lockup>small:last-child{grid-column:1/3;display:flex;justify-content:space-between;margin-top:5px}.brand-lockup i{font-style:italic;color:#78f5c6;font-size:14px;letter-spacing:0}.brand-signature{display:flex;justify-content:space-between;color:#748b7e;font:500 8px/1 Inter,sans-serif;letter-spacing:.15em;border-bottom:1px solid #34453c;padding-bottom:16px}
body .dh-hero{display:grid;grid-template-columns:1.2fr 1fr;align-items:center;gap:20px;text-align:left;padding:58px 20px 48px;overflow:hidden;isolation:isolate}.dh-hero:before{display:none}.dh-hero .eyebrow{border:0;border-radius:0;padding:0;background:transparent;letter-spacing:.18em;font-size:9px;color:#a6bdae}.dh-hero .eyebrow:before{border-radius:0;width:17px;height:3px;box-shadow:none;background:#78f5c6;transform:skewX(-25deg)}body .dh-hero h1{font:400 clamp(52px,6.8vw,98px)/1.03 var(--brand-display);letter-spacing:-.008em;max-width:none;margin:23px 0}.dh-hero h1 span{display:inline;background:none;-webkit-text-fill-color:var(--brand-mint);color:var(--brand-mint)}body .dh-hero p{max-width:430px;margin:0;color:#b3c0b8;font-size:14px;line-height:1.85}.dh-actions{justify-content:flex-start;gap:11px;margin:25px 0 22px}body .dh-actions button{display:flex;align-items:center;gap:25px;border:1px solid #78f5c6;border-radius:2px;box-shadow:none;background:#78f5c6;color:#08140e;font-size:10px;font-weight:700;letter-spacing:.03em;padding:15px 18px}body .dh-actions button.secondary{border-color:#45574c;background:transparent;color:#e0e5dc;box-shadow:none}body .dh-actions button:hover{background:#b8ffdf;border-color:#b8ffdf;color:#08140e}body .dh-actions button span{font-size:18px;line-height:1}.brand-hero-caption{display:flex;align-items:center;gap:12px;font-size:8px;letter-spacing:.14em;color:#869f91}.brand-slashes{font:italic 800 23px/1 Inter,sans-serif;letter-spacing:-3px;color:#78f5c6;padding-right:6px}
.brand-hero-art{position:relative;min-width:0;align-self:stretch;display:flex;align-items:center;justify-content:center;isolation:isolate;min-height:360px}.brand-hero-art:before{content:'';position:absolute;inset:8%;background:radial-gradient(ellipse,#4ee8a722,transparent 68%);filter:blur(20px);z-index:-1}.brand-hero-art>img{display:block;width:min(100%,390px);height:auto;position:relative;transform:rotate(-5deg);filter:drop-shadow(0 14px 24px #0007);animation:brand-arrive .8s ease-out both}.brand-orbit{position:absolute;width:92%;aspect-ratio:1;border:1px solid #65887524;border-radius:50%;transform:rotate(-25deg) scaleY(.78);z-index:-1}.orbit-two{width:74%}.orbit-three{width:112%;border-style:dashed;border-color:#719d8122}.brand-art-index{position:absolute;left:5%;top:0;font:500 9px Inter,sans-serif;letter-spacing:.1em;color:#6a8977}.brand-art-caption{position:absolute;bottom:0;right:3%;font:400 8px/1.8 Inter,sans-serif;letter-spacing:.15em;color:#6d8d79;text-align:right}.brand-art-caption b{color:#a0beac;font-weight:500}.brand-speed-mark{position:absolute;top:-15px;right:8%;font:italic 800 60px/1 Inter,sans-serif;letter-spacing:-10px;color:#78f5c61c;transform:skew(-8deg)}
.brand-principles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-top:1px solid #34453c;border-bottom:1px solid #34453c;margin:14px 0 20px}.brand-principles>div{display:grid;grid-template-columns:29px 1fr;gap:4px 9px;padding:19px 22px;border-right:1px solid #34453c}.brand-principles>div:last-child{border:0}.brand-principles span{grid-row:1/3;font:400 26px/1.25 var(--brand-display);color:#78f5c6}.brand-principles b{font:600 10px/1.4 Inter,sans-serif;letter-spacing:.08em}.brand-principles small{font-size:10px;color:#91a496}body #loading{font-size:10px;color:#8fa294;margin-bottom:15px}body .refresh-banner{border-radius:3px!important;background:#102019!important;border:1px solid #314c3e!important;font-size:12px;box-shadow:none}body .refresh-banner.stale{background:#32291a!important}
body nav{justify-content:space-between;gap:8px;border:1px solid #3d5546;border-radius:3px;background:#111b15f5;box-shadow:none;backdrop-filter:blur(18px);padding:0 18px;scrollbar-color:#3c6951 #111b15;scroll-margin-top:12px}body nav button{font-size:10px;color:#a8bbae;padding:20px 8px}body nav button.active{color:#78f5c6;border-color:#78f5c6}body nav button:hover{color:#eff6ee}body .eyebrow{color:#91debb;font-size:10px;letter-spacing:.14em}body article{background:linear-gradient(130deg,#14221b,#0f1915);border:1px solid #34483c;border-radius:5px;box-shadow:none}body .dh-observatory{border-top:2px solid #78f5c6;padding:28px!important}.dh-observatory:before{background:radial-gradient(circle,#78f5c610,transparent 70%)}body .dh-section-head h2{font-size:34px}.dh-section-head p{color:#adbcaf}.dh-selection{background:linear-gradient(130deg,#203a2c,#16261e);border:1px solid #41604c;border-radius:3px}.dh-selection .dh-chance{color:#8cf2bc;font-family:var(--brand-display);font-weight:400;letter-spacing:0}.dh-selection h3{color:#edf2e8}.dh-selection p,.dh-selection small{color:#b3c9b8}.dh-selection button{background:#78f5c6;border-radius:2px;color:#102016}.dh-chart text{fill:#adc0b1}.dh-chart .axis-title{fill:#d3ddcf}.dh-chart .gridline{stroke:#71947d30}.dh-chart-legend{color:#b2c5b5}.dh-chart-legend span:before{background:#78f5c6}.dh-chart-legend span:last-child:before{background:#d4b882}.dh-chart-caption{color:#9ab09f}.dh-prob-chart{border-color:#3b5143}
body .filters,body .picker{background:#0e1913;border:1px solid #314939;border-radius:4px}body input,body select,body .picker select{background:#17271d;color:#e7eee3;border:1px solid #47604e;border-radius:3px;font-size:12px}body label{color:#a7bba9}body .conferenceTabs button{border-radius:2px;background:#17281e;border-color:#3f5947;color:#bdd0bf}body .conferenceTabs button.active{background:#78f5c6;border-color:#78f5c6;color:#0a2113}body .gamecard{background:linear-gradient(130deg,#192b20,#122016);border-color:#3e5745;border-radius:4px;box-shadow:none}body .gamecard:hover{background:#203c2a;border-color:#78f5c6;box-shadow:none;transform:translateY(-2px)}body .gamecard .cardteam strong,body .boardStats b{font-family:var(--brand-display);font-weight:400;letter-spacing:0}body .hubheading h2{font:400 34px/1.2 var(--brand-display)}body .notice,body .similarbox,body .patterncard,body .contextcard,body .plainstat{background:#17271f;border-color:#3b5143;border-radius:4px;color:#c2d0c3}body .pill,body .signalbadge{background:#1e3b2a;border-color:#41634d;color:#a4e7bd;border-radius:2px}body .metertrack i,body .track i{background:linear-gradient(90deg,#359f79,#9bf4b9);box-shadow:none}body .forecast{background:linear-gradient(145deg,#1a2a20,#101c15);border-top:3px solid #78f5c6}body .score strong{font-family:var(--brand-display);font-weight:400}body th,body td{border-color:#344a3b}body .tablewrap th{color:#cfdfcf}body details{border-color:#344a3b}
body .sb-week{background:radial-gradient(ellipse at 90% 0,#78f5c612,transparent 55%),#101d15;border-color:#41634b;border-radius:5px;box-shadow:none}body .sb-week-head h2{font-family:var(--brand-display);font-weight:400;letter-spacing:.005em}body .sb-week-head h2 span{color:#78f5c6;text-shadow:none}body .sb-rail article.sb-card{background:radial-gradient(circle at 50% 20%,#69c69b17,transparent 45%),#15251b;border-color:#477456;border-radius:4px;box-shadow:none}body .sb-card:before{left:0;right:auto;width:42px;height:4px;box-shadow:none;background:#78f5c6;transform:skewX(-25deg);transform-origin:left}body .sb-rail article.sb-special{background:radial-gradient(circle at 50% 22%,#b88b3c23,transparent 50%),#242319;border-color:#b7a166;box-shadow:none}body .sb-special:before{background:#e9c883}body .sb-odds{font-family:var(--brand-display);font-weight:400;letter-spacing:0;color:#78f5c6;text-shadow:none}body .sb-special .sb-odds{color:#e9c883;text-shadow:none}body .sb-rule,body .sb-rule-active{border-radius:3px;background:linear-gradient(100deg,#49402055,#242319);border-color:#8f7b494d;box-shadow:none}.brand-seabiscuit-mark{width:21px;height:21px;object-fit:contain;vertical-align:middle;margin-right:3px;filter:sepia(1) saturate(1.6)}.sb-horse img{object-fit:contain;filter:sepia(1) saturate(1.6)}body .sb-badge{display:inline-flex;align-items:center;gap:2px;white-space:normal;font-size:9px}body .sb-card button.sb-report{border-radius:2px}body .sb-model b{font-variant-numeric:tabular-nums;color:#edf3e7}body .sb-location,body .sb-source,body .sb-coverage{color:#adbdab}body #parlays .parlay-categories button{border-radius:3px;background:#15251b;color:#dce6d5;border-color:#415a45}body #parlays .parlay-categories .selected{background:#284732;border-color:#78f5c6;box-shadow:inset 0 -3px #78f5c6}body #parlays .parlay-categories span{color:#aec2b0}body #parlays .parlay-hero,body #parlays .parlay-method{border-color:#3f5745;background:#14231a;border-radius:4px}body #parlays .parlay-hero h2{font-family:var(--brand-display);font-size:38px;font-weight:400;letter-spacing:0}body .coach-change-note{background:linear-gradient(130deg,#3f392149,#16332640);border-radius:4px}body #matchCoverage{background:#1a3024;color:#bfd2c2;border-color:#70a786}
body .brand-footer{border-top:1px solid #455a49;display:flex;align-items:center;justify-content:space-between;gap:25px;margin-top:60px;padding:30px 0;color:#8fa592;font-size:9px;letter-spacing:.05em}.brand-footer-name{display:flex;align-items:center;gap:12px;color:#eef2e5!important;text-decoration:none;font:400 21px/1.1 var(--brand-display);letter-spacing:.02em}.brand-footer img{object-fit:contain}.brand-download{color:#a9d9b9!important;text-decoration:none;font-size:10px}body .brand-footer>span{font-size:8px;letter-spacing:.12em}
@keyframes brand-arrive{from{opacity:0;transform:translateX(-20px) rotate(-5deg)}to{opacity:1;transform:translateX(0) rotate(-5deg)}}
@media(max-width:900px){body .dh-hero{padding:40px 0 35px;grid-template-columns:1.15fr 1fr;gap:0}body .dh-hero h1{font-size:clamp(48px,7.4vw,72px)}.brand-hero-art{min-height:310px}.brand-art-caption{font-size:7px}.brand-principles>div{padding:16px 10px;grid-template-columns:22px 1fr;gap:4px 7px}.brand-principles b{font-size:8px}.brand-principles small{font-size:9px}.brand-principles span{font-size:23px}body nav{justify-content:flex-start;gap:18px;overflow-x:auto}body nav button{white-space:nowrap}.brand-footer>span{display:none}}
@media(max-width:600px){body main{padding:0 5% 20px}body header.darkhorse-header{padding:0 5%}.masthead-foot>span:first-child{max-width:150px}body .masthead-foot{font-size:7px;letter-spacing:.05em;padding:12px 0;align-items:center}.dh-brand>img{width:60px;height:60px}body .dh-brand{gap:12px;margin:18px auto}.brand-lockup>strong{font-size:38px}.brand-lockup>small{font-size:7px}.brand-signature{font-size:6px;letter-spacing:.07em;padding-bottom:12px}body .dh-hero{padding:25px 0 30px;grid-template-columns:1fr;gap:12px}.brand-hero-art{grid-row:1;min-height:180px;height:180px;max-width:260px;width:100%;margin:auto}.brand-hero-art>img{height:185px;width:185px}.brand-orbit{max-width:215px}.orbit-two{max-width:170px}.orbit-three{max-width:250px}.brand-art-index{font-size:6px;left:0;top:15px}.brand-art-caption{display:none}.brand-speed-mark{font-size:40px;top:0;right:0}.brand-hero-copy{text-align:center}.dh-hero .eyebrow{font-size:7px;letter-spacing:.1em;justify-content:center}body .dh-hero h1{font-size:clamp(46px,12vw,68px);line-height:1.06;margin:17px 0}body .dh-hero p{font-size:12px;max-width:340px;margin:auto;line-height:1.8}.dh-actions{justify-content:center;gap:8px;margin:20px 0 17px}body .dh-actions button{font-size:8px;gap:11px;padding:13px 12px}.brand-hero-caption{justify-content:center;font-size:7px}.brand-principles{margin-top:0}.brand-principles>div{display:block;padding:12px 8px;text-align:center}.brand-principles span{display:block;font-size:23px;margin-bottom:5px}.brand-principles b{font-size:7px;line-height:1.7;display:block;letter-spacing:.02em}.brand-principles small{display:none}body #loading{font-size:9px;line-height:1.8}body nav{padding:0 9px;gap:18px}body nav button{font-size:10px;padding:16px 0}body article{padding:20px}body .dh-observatory{padding:20px!important}body .dh-section-head h2{font-size:30px}.dh-selection{padding:18px}.brand-footer-name{font-size:16px;gap:8px}.brand-footer img{width:38px;height:38px}.brand-download{font-size:8px}body .brand-footer{gap:12px;flex-wrap:wrap}body .sb-badge{font-size:8px}.brand-seabiscuit-mark{width:18px;height:18px}body .sb-week-head h2{font-size:36px}body .sb-week-head .eyebrow{font-size:8px;letter-spacing:.07em}}
@media(prefers-reduced-motion:reduce){.brand-hero-art>img{animation:none}body .gamecard:hover{transform:none}}

/* Pure black logo backing disappears into the dark brand surfaces. */
.dh-brand>img,.brand-hero-art>img,.brand-footer img,.brand-seabiscuit-mark,.sb-horse img{mix-blend-mode:screen}

body .dh-hero,.brand-hero-art{isolation:auto}.brand-hero-art>img{filter:none}.brand-orbit{z-index:0}.brand-hero-art:before{z-index:0}

'use strict';
// Charts use the same saved forecasts and market snapshots as the game reports.
const DarkhorseCharts=(()=>{
 let selected=null,scope='all';
 const ns='http://www.w3.org/2000/svg';
 function openGame(id){$('matchConference').value='all';fillGames();show(id);tab('lab');document.querySelector('nav').scrollIntoView({behavior:'smooth',block:'start'});}
 function selection(f){selected=f.id;const g=game(f),u=upsetInfo(f),q=forecast(f);$('dhSelection').innerHTML=`<div class="eyebrow">${u.home&&!g.neutral?'HOME UNDERDOG':'UNDERDOG WATCH'}</div><div class="dh-logo-row">${logo(g.away)}<span>at</span>${logo(g.home)}</div><h3>${esc(name(u.team))}</h3><div class="dh-chance">${pct(u.p)}</div><small>chance to win the game outright</small><p>${esc(name(g.away))} at ${esc(name(g.home))}<br>${esc(date(g))}</p><p>Sportsbook: ${esc(line(g))}<br>Model: ${esc(name(g.away))} ${q.a} · ${esc(name(g.home))} ${q.h}</p><button type="button" id="dhOpenGame">Explore this matchup ↗</button>`;$('dhOpenGame').onclick=()=>openGame(f.id);document.querySelectorAll('.dh-dot').forEach(e=>e.classList.toggle('selected',e.dataset.id===f.id));}
 function radar(fs){
  if(!$('dhRadarPlot'))return;
  const all=fs.filter(f=>upsetInfo(f).market),rows=all.filter(f=>scope!=='home'||(upsetInfo(f).home&&!game(f).neutral));
  const max=Math.max(10,Math.ceil(Math.max(0,...rows.map(f=>Math.abs(meta(game(f)).homeSpread)))/10)*10),w=680,h=290,left=44,right=660,top=18,bottom=245;
  const x=n=>left+n/max*(right-left),y=p=>bottom-p*(bottom-top);
  let grid='';for(let n=0;n<=100;n+=25)grid+=`<line class="gridline" x1="${left}" x2="${right}" y1="${y(n/100)}" y2="${y(n/100)}"/><text x="${left-9}" y="${y(n/100)+4}" text-anchor="end">${n}%</text>`;
  for(let n=0;n<=max;n+=max/4)grid+=`<text x="${x(n)}" y="267" text-anchor="middle">+${n}</text>`;
  $('dhRadarPlot').innerHTML=`<svg viewBox="0 0 ${w} ${h}" aria-label="Underdog win chance versus sportsbook point spread"><defs><linearGradient id="radarWash" x2="0" y2="1"><stop stop-color="#56edd3" stop-opacity=".12"/><stop offset="1" stop-color="#78f5c6" stop-opacity="0"/></linearGradient></defs><rect x="44" y="18" width="616" height="227" rx="8" fill="url(#radarWash)"/>${grid}<line x1="44" x2="660" y1="${y(.5)}" y2="${y(.5)}" stroke="#6d99a7" stroke-dasharray="4 5"/><text class="axis-title" x="352" y="287" text-anchor="middle">Sportsbook head start (points)</text>${rows.map(f=>{const u=upsetInfo(f),home=u.home&&!game(f).neutral,label=`${name(u.team)}: ${pct(u.p)} win chance, +${Math.abs(meta(game(f)).homeSpread)} spread`;return `<circle class="dh-dot" data-id="${esc(f.id)}" cx="${x(Math.abs(meta(game(f)).homeSpread))}" cy="${y(u.p)}" r="5.5" fill="${home?'#5cf4d1':'#d4b882'}" fill-opacity=".85" tabindex="0" role="button" aria-label="${esc(label)}"><title>${esc(label)}</title></circle>`}).join('')}</svg>`;
  $('dhRadarCaption').textContent=`${rows.length} games with posted spreads in your board filters. Higher dots mean a greater chance of an outright upset. The dashed line is 50%. ${fs.length-all.length} games have no market underdog and are excluded.`;
  document.querySelectorAll('.dh-dot').forEach(el=>{const select=()=>selection(rows.find(f=>f.id===el.dataset.id));el.onclick=select;el.onfocus=select;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};});
  $('dhPickList').innerHTML=rows.length?`<details><summary>Choose a game by name</summary><div class="dh-list-grid">${[...rows].sort((a,b)=>upsetInfo(b).p-upsetInfo(a).p).map(f=>`<button type="button" data-dh-pick="${esc(f.id)}">${esc(name(upsetInfo(f).team))} · ${pct(upsetInfo(f).p)}</button>`).join('')}</div></details>`:'';
  document.querySelectorAll('[data-dh-pick]').forEach(el=>el.onclick=()=>selection(rows.find(f=>f.id===el.dataset.dhPick)));
  const chosen=rows.find(f=>f.id===selected)||[...rows].sort((a,b)=>upsetInfo(b).p-upsetInfo(a).p)[0];if(chosen)selection(chosen);else $('dhSelection').innerHTML='<h3>No matching games</h3><p>Try another conference or schedule. Games need a posted spread to appear.</p>';
 }
 function margin(f){
  if(!$('dhMargin'))return;const g=game(f),q=forecast(f),sd=f.coreSd;if(!Number.isFinite(sd)||sd<=0)return;
  const limit=Math.ceil((Math.abs(q.margin)+sd*2.5)/10)*10,x=n=>30+(n+limit)/(limit*2)*340,y=n=>125-Math.exp(-.5*((n-q.margin)/sd)**2)*95;
  const points=Array.from({length:121},(_,i)=>{const n=-limit+i/120*2*limit;return `${x(n)},${y(n)}`}).join(' ');
  $('dhMargin').innerHTML=`<div class="eyebrow">EXPLORE THE RANGE</div><h3>How close could it be?</h3><div class="dh-chart"><svg viewBox="0 0 400 160" role="img" aria-label="Model distribution of the home team's winning margin"><defs><linearGradient id="marginWash" x2="0" y2="1"><stop stop-color="#68f7db" stop-opacity=".5"/><stop offset="1" stop-color="#78f5c6" stop-opacity=".04"/></linearGradient></defs><polygon points="30,125 ${points} 370,125" fill="url(#marginWash)"/><polyline points="${points}" fill="none" stroke="#72edd9" stroke-width="2"/><line x1="${x(0)}" x2="${x(0)}" y1="20" y2="128" stroke="#d4b882" stroke-dasharray="4 4"/><text x="30" y="148">${esc(name(g.away))} wins</text><text x="370" y="148" text-anchor="end">${esc(name(g.home))} wins</text><line id="dhMarginCursor" x1="${x(0)}" x2="${x(0)}" y1="20" y2="125" stroke="#fff"/></svg></div><label for="dhMarginSlider">Explore a winning margin</label><input type="range" id="dhMarginSlider" min="${-limit}" max="${limit}" value="0" step="1"><div class="range-ends"><span>Away by ${limit}</span><span>Home by ${limit}</span></div><p id="dhMarginReadout" class="dh-margin-pick" aria-live="polite"></p><p class="tiny">Move the marker to explore the model’s range. This does not change the forecast. The curve is a statistical estimate, not a guarantee.</p>`;
